def guidance_for(question, history=()):
    """Return relevant static references, never raw history or derived facts.

    Bounded user text resolves short follow-ups only. Selecting a reference is
    not proof its rule applies; explicit latest-topic questions are evaluated on
    their own so a previous food/vehicle question cannot label a new shipment.
    """
    text = str(question or '')[:4000]
    query = text
    reset = re.search(r'نقل|شحن[ةه]\s*(?:جديد|ثاني)|حمول[ةه]\s*(?:جديد|ثاني)|مرحبا|اهلا|أهلا|السلام|شكرا|شكرًا|\b(?:transport|new\s+shipment|hello|thanks)\b', text, re.I)
    if not reset and len(text.strip()) < 60 and not any(re.search(topic['match'], text, re.I) for topic in TOPICS):
        for entry in list(history or ())[-2:]:
            if isinstance(entry, dict):
                query += '\n' + str(entry.get('question') or entry.get('user') or entry.get('customer') or '')[:1500]
    matches = [topic for topic in TOPICS if re.search(topic['match'], query, re.I)]
    return CURRENT_RULES + '\n\n'.join(topic['text'] for topic in matches)
